/* GOV View — light, plain, readable. */
:root {
  color-scheme: light;
  --paper: #faf8f3;
  --surface: #ffffff;
  --sunk: #f3f0e8;
  --ink: #1b1f23;
  --ink-2: #454d55;
  --ink-3: #6b737b;
  --rule: #e4dfd4;
  --rule-strong: #cfc8b8;
  --accent: #0f5c63;
  --accent-hover: #0a474d;
  --accent-soft: #e2eeec;
  --ok: #1e6b3a;
  --ok-soft: #e5f1e8;
  --warn: #8a5a00;
  --warn-soft: #faefd6;
  --bad: #a1322d;
  --bad-soft: #f8e3e0;
  --info: #2b4f7e;
  --info-soft: #e5ecf5;
  --radius: 6px;
  --font-sans: "Segoe UI", system-ui, sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }
html { background: var(--paper); -webkit-text-size-adjust: 100%; }
body { margin: 0; min-width: 320px; color: var(--ink); background: var(--paper); font: 15px/1.5 var(--font-sans); -webkit-font-smoothing: antialiased; }
h1, h2, h3 { margin: 0; }
p { margin: 0; }
a { color: var(--accent); text-underline-offset: 2px; }
a:hover { color: var(--accent-hover); }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; }
:focus-visible { outline: 3px solid #f2b705; outline-offset: 2px; }
::selection { background: #cfe5e2; }
.visually-hidden { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* Buttons */
.button-primary, .button-quiet { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 44px; padding: 0 18px; border-radius: var(--radius); font-weight: 600; text-decoration: none; }
