/* Page frame */
.app { display: grid; grid-template-rows: auto auto minmax(0, 1fr); height: 100svh; }
.site-header { display: flex; align-items: center; gap: 28px; height: 56px; padding: 0 20px; background: var(--surface); border-bottom: 1px solid var(--rule); }
