.result:hover { background: var(--paper); color: var(--ink); }
.result[aria-current="true"] { background: var(--accent-soft); box-shadow: inset 3px 0 0 var(--accent); }
.result-meta { font-size: 12.5px; color: var(--ink-3); }
.result-title { font-weight: 600; font-size: 16px; line-height: 1.3; }
.result-authority { font-size: 13.5px; color: var(--ink-2); }
.result-foot { display: flex; flex-wrap: wrap; gap: 4px 14px; margin-top: 4px; font-size: 13px; }
.result-fit { display: inline-flex; align-items: center; gap: 5px; margin-top: 4px; font-size: 13px; font-weight: 600; }
.fit-matches-published-criteria { color: var(--ok); }
.fit-does-not-match { color: var(--bad); }
.fit-needs-verification { color: var(--warn); }
.show-more { display: flex; justify-content: center; padding: 8px 20px 96px; margin-top: -76px; }
.loading-note { padding: 24px 22px; color: var(--ink-3); }
.source-list { list-style: none; padding: 0 !important; display: grid; gap: 6px; }
.source-list li { display: grid; }
.source-list small { color: var(--ink-3); font-size: 12.5px; overflow-wrap: anywhere; }
.empty { padding: 28px 22px; display: grid; gap: 10px; color: var(--ink-2); justify-items: start; }
.empty strong { color: var(--ink); }

/* Status, always text + colour */
.status-dot { display: inline-flex; align-items: center; gap: 6px; color: var(--ink-2); }
.status-dot::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--ink-3); }
.status-open::before, .status-extended::before { background: var(--ok); }
.status-closed::before, .status-cancelled::before { background: #9aa1a8; }
.status-stale::before, .status-uncertain::before { background: #d49a1f; }
.status-upcoming::before { background: var(--info); }
.deadline { color: var(--ink-2); }
.deadline.urgent { color: var(--bad); font-weight: 600; }
.status-tag { display: inline-block; padding: 2px 9px; border-radius: 4px; font-size: 13px; font-weight: 600; background: var(--sunk); color: var(--ink-2); }
.status-tag.status-open, .status-tag.status-extended { background: var(--ok-soft); color: var(--ok); }
.status-tag.status-cancelled { background: var(--bad-soft); color: var(--bad); }
.status-tag.status-stale, .status-tag.status-uncertain { background: var(--warn-soft); color: var(--warn); }
.status-tag.status-upcoming { background: var(--info-soft); color: var(--info); }
.tone-ok { color: var(--ok); flex: none; }
.tone-bad { color: var(--bad); flex: none; }
.tone-warn { color: var(--warn); flex: none; }

/* Map */
.map-pane { position: relative; min-height: 0; background: #dfe8ea; }
.map-toolbar { position: absolute; z-index: 5; top: 12px; left: 12px; right: 12px; display: flex; justify-content: space-between; align-items: center; gap: 8px; pointer-events: none; }
.map-toolbar > * { pointer-events: auto; }
.map-toolbar > div { display: flex; gap: 6px; }
.map-where { white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius); font-weight: 600; font-size: 14px; }
.map-button { white-space: nowrap; display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 0 11px; border: 1px solid var(--rule-strong); border-radius: var(--radius); background: var(--surface); font-size: 13.5px; }
.map-button:hover { border-color: var(--ink-3); }
.map-button[aria-pressed="true"] { background: var(--ink); color: #fff; border-color: var(--ink); }
@media (max-width: 1279px) and (min-width: 960px) { .map-caption { display: none; } }
.map-caption { position: absolute; z-index: 5; left: 12px; bottom: 12px; max-width: min(440px, calc(100% - 24px)); padding: 6px 10px; background: rgb(255 255 255 / 0.92); border: 1px solid var(--rule); border-radius: var(--radius); font-size: 12.5px; color: var(--ink-2); }
.map-message { position: absolute; inset: 0; display: grid; place-content: center; gap: 8px; padding: 24px; text-align: center; color: var(--ink-2); }
.map-message-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-top: 6px; }
.map-message-actions button { min-height: 36px; padding: 0 12px; border: 1px solid var(--rule-strong); border-radius: 999px; background: var(--surface); }

/* Reader */
.reader-back { display: none; }
.reader-empty { margin: auto; padding: 32px; max-width: 280px; text-align: center; color: var(--ink-3); }
.job-article { display: flex; flex-direction: column; min-height: 100%; }
.article-scroll { flex: 1; padding: 24px 24px 12px; }
.eyebrow { font-size: 13px; color: var(--ink-3); }
.article-title { margin-top: 4px; font: 600 26px/1.2 var(--font-serif); letter-spacing: -0.01em; }
.article-authority { margin-top: 6px; color: var(--ink-2); }
.article-status { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; margin-top: 14px; font-size: 14px; }
.article-status .icon-button { margin-left: auto; }
.status-note { margin-top: 10px; color: var(--ink-2); font-size: 14px; }
.job-article section { padding: 18px 0; border-top: 1px solid var(--rule); margin-top: 18px; }
.job-article section + section { margin-top: 0; }
.job-article h3 { font: 600 17px/1.3 var(--font-serif); margin-bottom: 10px; }
.facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin: 0; }
.facts.stacked { grid-template-columns: 1fr; margin-top: 14px; }
.facts div { min-width: 0; }
.facts dt { display: flex; align-items: center; gap: 4px; font-size: 13px; color: var(--ink-3); }
.facts dd { margin: 2px 0 0; font-weight: 500; overflow-wrap: anywhere; }
.fine-print { margin-top: 10px; font-size: 13.5px; color: var(--ink-3); }
.fine-print svg { vertical-align: -2px; }
.stages { margin: 0; padding-left: 20px; }
.stages li + li { margin-top: 4px; }
.sources { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.sources li { display: flex; gap: 10px; color: var(--ink-3); }
.sources li > div { display: grid; gap: 1px; min-width: 0; }
.sources a, .sources span { color: var(--ink); font-weight: 500; }
.sources a { color: var(--accent); display: inline-flex; gap: 3px; align-items: center; }
.sources small { font-size: 12.5px; color: var(--ink-3); }
.history { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; font-size: 14px; }
.history time { display: block; font-size: 12.5px; color: var(--ink-3); }
.article-foot { position: sticky; bottom: 0; padding: 14px 24px 18px; background: var(--surface); border-top: 1px solid var(--rule); }
.article-foot p { margin-top: 8px; font-size: 13px; color: var(--ink-3); text-align: center; }

.eligibility-empty { display: grid; gap: 12px; justify-items: start; padding: 14px; background: var(--paper); border: 1px dashed var(--rule-strong); border-radius: var(--radius); color: var(--ink-2); font-size: 14px; }
.assessments { display: grid; gap: 6px; }
.assessment { border: 1px solid var(--rule); border-radius: var(--radius); background: var(--surface); }
.assessment summary { display: flex; align-items: center; gap: 10px; min-height: 46px; padding: 8px 12px; cursor: pointer; list-style: none; }
.assessment summary::-webkit-details-marker { display: none; }
.assessment-label { flex: 1; font-weight: 500; }
.assessment-result { font-size: 14px; font-weight: 600; }
.result-matches-published-criteria .assessment-result { color: var(--ok); }
.result-does-not-match .assessment-result { color: var(--bad); }
.result-needs-verification .assessment-result { color: var(--warn); }
.assessment-chevron { color: var(--ink-3); transition: transform 0.15s; }
.assessment[open] .assessment-chevron { transform: rotate(180deg); }
.assessment ul { list-style: none; margin: 0; padding: 4px 12px 12px 40px; display: grid; gap: 10px; font-size: 14px; }
.assessment li { display: flex; gap: 8px; }
.assessment li svg { margin-top: 3px; }
.assessment blockquote { margin: 4px 0 0; padding-left: 10px; border-left: 2px solid var(--rule-strong); color: var(--ink-3); font-size: 13px; }

/* Profile dialog */
.profile-dialog { width: min(640px, calc(100vw - 24px)); max-height: calc(100svh - 24px); padding: 0; border: 1px solid var(--rule-strong); border-radius: 10px; background: var(--surface); color: var(--ink); box-shadow: 0 20px 50px rgb(27 31 35 / 0.18); }
.profile-dialog::backdrop { background: rgb(27 31 35 / 0.45); }
.profile-dialog form { display: flex; flex-direction: column; max-height: calc(100svh - 26px); }
.dialog-head { display: flex; gap: 12px; padding: 20px 20px 12px; }
.dialog-head h2 { font: 600 22px/1.2 var(--font-serif); }
.dialog-head p { margin-top: 6px; color: var(--ink-2); font-size: 14px; }
.privacy-note { display: flex; align-items: center; gap: 8px; margin: 0 20px; padding: 8px 12px; background: var(--accent-soft); border-radius: var(--radius); color: var(--accent); font-size: 13.5px; }
.dialog-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 16px; padding: 16px 20px; }
.form-grid label { display: grid; gap: 5px; align-content: start; font-size: 14px; font-weight: 500; }
.form-grid input:not([type="checkbox"]), .form-grid select { height: 42px; width: 100%; padding: 0 10px; border: 1px solid var(--rule-strong); border-radius: var(--radius); background: var(--surface); font-weight: 400; }
.form-grid input:focus, .form-grid select:focus { border-color: var(--accent); outline: 0; box-shadow: 0 0 0 3px var(--accent-soft); }
.form-grid small { color: var(--ink-3); font-weight: 400; font-size: 12.5px; }
.form-grid label.check { display: flex; align-items: center; gap: 9px; font-weight: 400; min-height: 42px; }
.form-grid label.check input { width: 18px; height: 18px; accent-color: var(--accent); }
.form-grid .wide { grid-column: 1 / -1; }
.dialog-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 14px 20px; border-top: 1px solid var(--rule); }
.dialog-foot > div { display: flex; gap: 8px; }

.toast { position: fixed; z-index: 50; left: 50%; bottom: 24px; transform: translateX(-50%); max-width: calc(100vw - 32px); padding: 10px 16px; border-radius: var(--radius); background: var(--ink); color: #fff; font-size: 14px; overflow-wrap: anywhere; }
.view-switch { display: none; }

/* Coverage and single-job pages */
.page { overflow-y: auto; }
.page-inner { max-width: 1040px; margin: 0 auto; padding: 36px 20px 64px; }
.page-inner h1 { font: 600 32px/1.15 var(--font-serif); letter-spacing: -0.015em; }
.lede { margin-top: 10px; max-width: 680px; color: var(--ink-2); font-size: 16.5px; }
.coverage-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; margin-top: 28px; }
.coverage-card { display: grid; gap: 10px; align-content: start; padding: 18px; background: var(--surface); border: 1px solid var(--rule); border-radius: 8px; }
.coverage-card h2 { font: 600 20px/1.2 var(--font-serif); }
.coverage-card dl { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; margin: 0; font-size: 14px; }
.coverage-card dt { color: var(--ink-3); }
.coverage-card dd { margin: 0; }
.coverage-card ul { margin: 0; padding-left: 18px; font-size: 14px; color: var(--ink-2); }
.coverage-state { font-weight: 600; font-size: 14px; }
.coverage-state.verified-listings { color: var(--ok); }
.coverage-state.sources-checked-no-current { color: var(--info); }
.coverage-state.no-verified-listings { color: var(--warn); }
.coverage-heading, .world-directory h2, .country-coverage h2 { margin-top: 32px; font: 600 23px/1.25 var(--font-serif); }
.coverage-card h3 { font: 600 20px/1.2 var(--font-serif); }
.world-directory { margin-top: 42px; }
.world-directory > p { margin-top: 8px; color: var(--ink-2); }
.country-search { display: grid; gap: 5px; max-width: 420px; margin-top: 20px; font-weight: 600; }
.country-search input { width: 100%; min-height: 44px; padding: 8px 12px; border: 1px solid var(--rule-strong); border-radius: var(--radius); background: var(--surface); }
.country-results { margin: 12px 0; color: var(--ink-3); font-size: 14px; }
.country-directory { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 8px; margin: 0; padding: 0; list-style: none; }
.country-directory a { display: grid; gap: 2px; height: 100%; padding: 10px 12px; background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius); text-decoration: none; }
.country-directory a:hover { border-color: var(--accent); }
.country-directory small, .country-directory a > span:last-child { color: var(--ink-3); font-size: 12px; }
.country-coverage { max-width: 800px; }
.country-coverage h1 { margin-top: 20px; }
.country-coverage h1 small { font: 500 15px var(--font-sans); color: var(--ink-3); }
.country-coverage section { margin-top: 24px; }
.country-coverage section h2 { margin: 0 0 8px; }
.country-coverage section p + p { margin-top: 8px; }
.country-coverage ul { margin: 8px 0 0; padding-left: 22px; }
.coverage-facts { display: grid; grid-template-columns: minmax(150px, 200px) 1fr; gap: 8px 16px; margin: 24px 0; padding: 18px; background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius); }
.coverage-facts dt { color: var(--ink-3); }
.coverage-facts dd { margin: 0; }
.country-source-list { display: grid; gap: 12px; list-style: none; padding: 0 !important; }
.country-source-list li { display: grid; gap: 6px; padding: 12px; background: var(--surface); border: 1px solid var(--rule); border-radius: var(--radius); overflow-wrap: anywhere; }
.country-source-list span, .country-source-list small { color: var(--ink-2); }
.source-research, .source-gap { padding-top: 8px; border-top: 1px solid var(--rule); }
.source-research strong, .source-gap strong { font-size: 14px; }
.source-research p, .source-gap p, .source-search-help { color: var(--ink-2); font-size: 14px; line-height: 1.6; }
.source-search-help { max-width: 560px; margin-top: 8px; }
.source-clear { min-height: 44px; padding: 8px 12px; border: 1px solid var(--rule-strong); border-radius: var(--radius); background: var(--surface); color: var(--ink); cursor: pointer; }
.job-page { max-width: 760px; margin: 0 auto; background: var(--surface); border-left: 1px solid var(--rule); border-right: 1px solid var(--rule); min-height: 100%; }
.back-link { display: inline-flex; align-items: center; gap: 6px; margin: 18px 24px 0; font-size: 14px; }

/* Tablet: narrower columns */
@media (max-width: 1279px) {
  .explore { grid-template-columns: minmax(310px, 350px) minmax(0, 1fr) minmax(340px, 380px); }
  .facts { grid-template-columns: 1fr 1fr; }
}

/* Phone and small tablet: list first, map on request, details full screen */
@media (max-width: 959px) {
  .site-header { gap: 14px; padding: 0 12px; }
  .site-header nav { gap: 14px; }
  .site-header nav a { font-size: 13.5px; }
  .profile-button span { display: none; }
  .site-header nav .long { display: none; }
  .site-header nav .short { display: inline; }
  .search-field kbd { display: none; }
  .finder h1 { font-size: 20px; }
  .profile-button { padding: 0 10px; }
  .explore { grid-template-columns: 1fr; position: relative; }
  .finder { border-right: 0; }
  .map-pane { display: none; }
  .explore[data-mobile-view="map"] .finder { display: none; }
  .explore[data-mobile-view="map"] .map-pane { display: block; }
  .reader { display: none; }
  .explore[data-reader-open="true"] .reader { display: flex; position: fixed; inset: 0; z-index: 30; border: 0; }
  .reader-back { display: inline-flex; align-items: center; gap: 6px; margin: 10px 12px 0; min-height: 44px; padding: 0 8px; border: 0; background: none; color: var(--accent); font-weight: 600; align-self: flex-start; }
  .article-scroll { padding: 8px 16px 12px; }
  .article-foot { padding: 12px 16px 16px; }
  .view-switch { display: inline-flex; align-items: center; gap: 8px; position: fixed; z-index: 20; left: 50%; bottom: 18px; transform: translateX(-50%); min-height: 44px; padding: 0 18px; border: 0; border-radius: 999px; background: var(--ink); color: #fff; font-weight: 600; box-shadow: 0 6px 18px rgb(27 31 35 / 0.25); }
  .map-caption { bottom: 72px; }
  .form-grid { grid-template-columns: 1fr; }
  .facts { grid-template-columns: 1fr 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}

.language-profile { margin: 20px 24px; padding: 16px; border: 1px solid var(--line, #d4d8d3); border-radius: 8px; }
.language-profile legend { font-weight: 650; }
.language-skill-row { display: grid; grid-template-columns: 1.5fr 1fr 1fr auto; gap: 8px; align-items: end; margin: 14px 0; }
.language-skill-row label { display: grid; gap: 5px; font-size: 13px; }
.language-skill-row select { width: 100%; padding: 8px; border: 1px solid #bac3bd; border-radius: 5px; background: white; color: #182a25; }
.language-requirements { padding-left: 20px; }
.language-requirements li { margin: 14px 0; }
@media (max-width: 640px) { .language-skill-row { grid-template-columns: 1fr 1fr; } .language-profile { margin: 16px; } }
